"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["37432"],{72498(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.pressuposto_tambem_item","status":422,"titulo":"O fato \xe9 item e pressuposto do mesmo modelo"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.pressuposto_tambem_item","requisitos":[],"oQueAconteceu":["Um fato da lista `pressupostos` do `conteudo` do modelo, enviado na cria\xe7\xe3o (`POST /api/configuracao/admin/modelos-formulario`) ou na atualiza\xe7\xe3o (`PUT /api/configuracao/admin/modelos-formulario/{id}`), tamb\xe9m \xe9 o `fatoCodigo` de um dos `itens` do mesmo modelo, ou de um campo de grupo (um item de `subitens` de um dos `grupos`). Ou o formul\xe1rio coleta o fato, ou o recebe da inscri\xe7\xe3o como pressuposto. A confer\xeancia olha os itens e os campos dos grupos do modelo, comparando os c\xf3digos depois de aparados e normalizados.","A recusa vem na lista `errors` da resposta, com `field` igual a `conteudo.pressupostos[i]`, em que `i` \xe9 a posi\xe7\xe3o do pressuposto. A mensagem cita o c\xf3digo do fato. A confer\xeancia s\xf3 \xe9 feita depois que o conte\xfado foi lido sem recusa de leitura, e num modelo que n\xe3o \xe9 o de inscri\xe7\xe3o. Nada \xe9 gravado. Na atualiza\xe7\xe3o, a busca do modelo vem antes das valida\xe7\xf5es de dom\xednio do conte\xfado: com um `{id}` que n\xe3o existe, a resposta \xe9 [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado). S\xf3 a leitura do corpo vem antes da busca: campo n\xe3o anul\xe1vel ausente ou nulo (como `nome`) \xe9 recusado com 400, sem c\xf3digo deste cat\xe1logo, mesmo com `{id}` inexistente."],"comoResolver":["Retire o fato de `pressupostos`, se o modelo deve colet\xe1-lo, ou retire o item que o coleta, se ele deve vir da inscri\xe7\xe3o, e repita o pedido."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);